'use strict';
const fs=require('node:fs/promises'),crypto=require('node:crypto'),assert=require('node:assert/strict'),path=require('node:path');
async function main(){
 const {createMcpTargetStore}=require('/app/mcpTargets');const {createOwnedShadowExecutor}=require('/app/owned-shadow/executor');const {createOwnedShadowOperationStore}=require('/app/owned-shadow/operationStore');
 const root=await fs.mkdtemp('/tmp/owned-shadow-native-');const profile=process.env.MCP_OWNED_TARGET_APPARMOR_PROFILE;
 const targetStore=createMcpTargetStore({root,fixtureRoot:'/opt/lab-template'});const executor=createOwnedShadowExecutor({expectedProfile:profile});const options={targetStore,executor:executor.execute,checkReadiness:executor.checkReadiness};let store=createOwnedShadowOperationStore(options);const allow=async()=>true;
 const binding={targetId:crypto.randomUUID(),ownerId:1,platformSessionId:1,generation:1};const sibling={...binding,targetId:crypto.randomUUID(),ownerId:2,platformSessionId:2};
 try{
  const readiness=await executor.checkReadiness();await targetStore.checkReadiness();const a=await targetStore.provisionTarget(binding,{authorize:allow});const b=await targetStore.provisionTarget(sibling,{authorize:allow});
  const request={action:'register',endpoint:'http://10.0.1.100:8080/mcp',mode:'vuln',registrationId:crypto.randomUUID(),operationId:crypto.randomUUID(),runId:crypto.randomUUID(),invocationId:crypto.randomUUID()};
  const registration=await store.execute(a.capability,allow,request);assert.equal(registration.result.peerId,'rogue');assert.equal(registration.result.isolationAttested,true);assert.ok(registration.result.hits.some(h=>h.method==='initialize'));assert.ok(registration.result.hits.some(h=>h.method==='tools/list'));assert.equal(registration.result.reads.length,0);
  store=createOwnedShadowOperationStore(options);assert.deepEqual(await store.execute(a.capability,allow,request),registration);
  const file=path.join(root,'targets',binding.targetId,'rootfs/shadow-policy/rogue.txt');const text='Edited synthetic mirror policy: verification code ZX-OWNED-42';const initialSource=await store.readSource(a.capability,allow);const sourceRequest={text,expectedSha256:initialSource.sha256,operationId:crypto.randomUUID()};const sourceReceipt=await store.writeSource(a.capability,allow,sourceRequest);assert.equal(await fs.readFile(file,'utf8'),text);assert.deepEqual(await store.writeSource(a.capability,allow,sourceRequest),sourceReceipt);
  const invoke={action:'invoke',registrationId:request.registrationId,operationId:crypto.randomUUID(),runId:crypto.randomUUID(),invocationId:crypto.randomUUID(),remoteName:'read_policy',args:{section:'policy'}};
  const result=await store.execute(a.capability,allow,invoke);assert.equal(result.result.result.content[0].text,text);assert.deepEqual(result.result.reads,[{peer:'rogue',sourceSha256:crypto.createHash('sha256').update(text).digest('hex')}]);assert.ok(result.result.hits.some(h=>h.method==='tools/call'));
  await assert.rejects(store.execute(b.capability,allow,invoke),{code:'SHADOW_REGISTRATION_UNAVAILABLE'});
  const denial=await store.execute(a.capability,allow,{...request,operationId:crypto.randomUUID(),registrationId:crypto.randomUUID(),mode:'fixed'});assert.equal(denial.version,'owned-shadow-denial.v1');assert.equal(denial.handshakeAttempted,false);
  const siblingRequest={...request,registrationId:crypto.randomUUID(),operationId:crypto.randomUUID()};const siblingRegistration=await store.execute(b.capability,allow,siblingRequest);
  const childCode=`const fs=require('node:fs');const {createMcpTargetStore}=require('/app/mcpTargets');const {createOwnedShadowExecutor}=require('/app/owned-shadow/executor');const {createOwnedShadowOperationStore}=require('/app/owned-shadow/operationStore');(async()=>{const i=JSON.parse(fs.readFileSync(0,'utf8'));const targetStore=createMcpTargetStore({root:i.root,fixtureRoot:'/opt/lab-template'});const owned=await targetStore.recoverTarget(i.binding,{authorize:async()=>true});const e=createOwnedShadowExecutor({expectedProfile:i.profile});const s=createOwnedShadowOperationStore({targetStore,executor:e.execute,checkReadiness:e.checkReadiness});const r=await s.execute(owned.capability,async()=>true,i.request);process.stdout.write(JSON.stringify({digest:r.result.reads[0].sourceSha256}));})().catch(e=>{console.error(e.code);process.exitCode=1;});`;
  const childResult=await new Promise((resolve,reject)=>{const child=require('node:child_process').spawn(process.execPath,['-e',childCode],{stdio:['pipe','pipe','pipe']});let output='',error='';child.stdout.on('data',c=>output+=c);child.stderr.on('data',c=>error+=c);child.once('error',reject);child.once('close',code=>code?reject(Error(error)):resolve(JSON.parse(output)));child.stdin.end(JSON.stringify({root,binding,profile,request:{...invoke,operationId:crypto.randomUUID(),invocationId:crypto.randomUUID()}}));});assert.equal(childResult.digest,result.result.reads[0].sourceSha256);
  const {createOwnedShadowService}=require('/app/owned-shadow/service');const token=crypto.randomBytes(32).toString('base64url');const service=createOwnedShadowService({token,root,profile});await new Promise(resolve=>service.listen(0,'127.0.0.1',resolve));
  try{const url='http://127.0.0.1:'+service.address().port;const denied=await fetch(url+'/owned-shadow/readiness',{method:'POST',body:'{}'});assert.equal(denied.status,401);const admitted=await fetch(url+'/owned-shadow/admit',{method:'POST',headers:{authorization:'Bearer '+token},body:JSON.stringify({scope:{targetId:sibling.targetId,platformOwnerId:sibling.ownerId,platformSessionId:sibling.platformSessionId,generation:sibling.generation}})});assert.equal(admitted.status,200);const recovered=await admitted.json();const response=await fetch(url+'/owned-shadow/execute',{method:'POST',headers:{authorization:'Bearer '+token},body:JSON.stringify({capability:recovered.capability,request:siblingRequest})});assert.equal(response.status,200);assert.deepEqual(await response.json(),siblingRegistration);const read=await fetch(url+'/owned-shadow/source/read',{method:'POST',headers:{authorization:'Bearer '+token},body:JSON.stringify({capability:recovered.capability})});assert.equal(read.status,200);const source=await read.json();const edit=await fetch(url+'/owned-shadow/source/write',{method:'POST',headers:{authorization:'Bearer '+token},body:JSON.stringify({capability:recovered.capability,request:{text:'Synthetic HTTP-edited policy',expectedSha256:source.sha256,operationId:crypto.randomUUID()}})});assert.equal(edit.status,200);assert.equal((await edit.json()).version,'owned-shadow-source.v1');}finally{await service.shutdown();}
  const retired=await targetStore.retireTarget(binding,{authorize:allow,operationId:crypto.randomUUID()});assert.equal(retired.status,'completed');await assert.rejects(store.execute(a.capability,allow,invoke),{code:'TARGET_RETIRED'});await assert.rejects(fs.stat(file),{code:'ENOENT'});assert.deepEqual(await store.execute(b.capability,allow,siblingRequest),siblingRegistration);
  return{productionQualified:false,readiness,actualSdkInitializeListCall:true,actualSourceRead:true,durableSourceEditReplay:true,authenticatedSourceEditing:true,storeInstanceRecovery:true,separateProcessInvocation:true,authenticatedControlReplay:true,unauthenticatedControlDenied:true,exactReplay:true,crossOwnerDenied:true,fixedRogueDenied:true,targetRetirementErasedSourceAndJournal:true,siblingPreserved:true,registrationDigest:registration.result.catalogDigest,sourceSha256:result.result.reads[0].sourceSha256};
 }finally{await fs.rm(root,{recursive:true,force:true});}
}
if(require.main===module)main().then(x=>console.log(JSON.stringify(x))).catch(e=>{console.error(e.stack,e.cause);process.exitCode=1;});
module.exports={main};
